edits.replacement:
// v16.xx, seen on the 4K What's New screenshot (2026-10-08): a line was cut mid-sentence (In co-op your teammate...) even when a
// whole sentence fitted. When one does, the line ends at that full stop; otherwise it is cut at a word as before.
cut=rest.slice(0,WN_TAIL);
if(cut.lastIndexOf('. ')>=WN_TAIL*0.4) return head+' '+rest.slice(0,cut.lastIndexOf('. ')+1);
cut=cut.replace(/\s+\S*$/,'');

check:
{v:'VER',what:'a What is New line ends at a whole sentence when one fits: a long line is cut at its last full stop inside the limit, not mid-sentence with dots',
 run:function(){
   if(typeof wnShort!=='function'||typeof WN_TAIL!=='number') return 'SKIP: no card shortener here';
   var bad=[], s1, s2, r1, r2, pad=function(n){ return new Array(n+1).join('zq '); };
   s1='ZQHEAD. '+pad(Math.round(WN_TAIL*0.25))+'zqend. '+pad(WN_TAIL);
   r1=wnShort(s1);
   if(!/zqend\.$/.test(r1)) bad.push('a line with a sentence end inside the limit ends as ...'+r1.slice(-24));
   s2='ZQHEAD. '+pad(WN_TAIL);
   r2=wnShort(s2);
   if(!/\.\.\.$/.test(r2)) bad.push('control: a line with no sentence end inside the limit lost its dots');
   return bad.length?bad.join('; '):null; }},
